-- Create "roles" table
CREATE TABLE "roles" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "name" character varying NOT NULL,
  "description" character varying NULL,
  PRIMARY KEY ("id")
);
-- Create "users" table
CREATE TABLE "users" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "first_name" character varying NOT NULL,
  "last_name" character varying NOT NULL,
  "email" character varying NOT NULL,
  "email_verified" boolean NOT NULL DEFAULT false,
  "password" character varying NULL,
  "sign_up_method" character varying NOT NULL DEFAULT 'register',
  "role_users" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "users_roles_users" FOREIGN KEY ("role_users") REFERENCES "roles" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create index "users_email_key" to table: "users"
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
-- Create "projects" table
CREATE TABLE "projects" (
  "id" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "name" character varying NOT NULL,
  "public_id" character varying NOT NULL,
  "user_projects" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "projects_users_projects" FOREIGN KEY ("user_projects") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create index "projects_public_id_key" to table: "projects"
CREATE UNIQUE INDEX "projects_public_id_key" ON "projects" ("public_id");
-- Create "action_models" table
CREATE TABLE "action_models" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "name" character varying NOT NULL,
  "description" character varying NOT NULL,
  "parameters" jsonb NOT NULL,
  "rules" jsonb NOT NULL,
  "required_feature" character varying NULL,
  "version" bigint NOT NULL DEFAULT 1,
  "project_id" character varying NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "action_models_projects_actions" FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create "api_keys" table
CREATE TABLE "api_keys" (
  "id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "name" character varying NOT NULL,
  "key_prefix" character varying NOT NULL,
  "key_hash" character varying NOT NULL,
  "status" character varying NOT NULL DEFAULT 'active',
  "last_used_at" timestamptz NULL,
  "expires_at" timestamptz NULL,
  "project_id" character varying NOT NULL,
  "created_by" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "api_keys_projects_api_keys" FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "api_keys_users_created_api_keys" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create "audit_records" table
CREATE TABLE "audit_records" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "project_id" character varying NULL,
  "prompt" text NOT NULL,
  "proposed_action" jsonb NULL,
  "validated" boolean NOT NULL DEFAULT false,
  "final_response" jsonb NULL,
  "action_id" bigint NULL,
  "user_id" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "audit_records_action_models_audit_records" FOREIGN KEY ("action_id") REFERENCES "action_models" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "audit_records_users_audit_records" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create "user_invitations" table
CREATE TABLE "user_invitations" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "invite_url" character varying NOT NULL,
  "status" character varying NOT NULL DEFAULT 'pending',
  "user_invitations" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_invitations_users_invitations" FOREIGN KEY ("user_invitations") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create "user_meta" table
CREATE TABLE "user_meta" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "last_logged_in" timestamptz NULL,
  "last_active_project" character varying NULL,
  "user_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_meta_projects_user_metas" FOREIGN KEY ("last_active_project") REFERENCES "projects" ("id") ON UPDATE NO ACTION ON DELETE SET NULL,
  CONSTRAINT "user_meta_users_meta" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "user_meta_user_id_key" to table: "user_meta"
CREATE UNIQUE INDEX "user_meta_user_id_key" ON "user_meta" ("user_id");
-- Create "user_password_secrets" table
CREATE TABLE "user_password_secrets" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "secret" character varying NOT NULL,
  "user_password_secret" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_password_secrets_users_password_secret" FOREIGN KEY ("user_password_secret") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "user_password_secrets_user_password_secret_key" to table: "user_password_secrets"
CREATE UNIQUE INDEX "user_password_secrets_user_password_secret_key" ON "user_password_secrets" ("user_password_secret");
